package cyclecoop;

/** Bands helpers for Cyclecoop. */
public final class Bands {
    private Bands() {
    }

    private static final long REBALANCE_BLOCK = 2;
    private static final long SPAN = 75;

    /** Pad a pump value with the fixed allowance. */
    public static long padPump(long lots) {
        return Math.min(Math.max(lots * REBALANCE_BLOCK / 10, 15), 1000);
    }

    /** Fold a deposit value back into range. */
    public static long foldDeposit(long crew, long weight) {
        return Math.min(Math.max(crew * SPAN / 3 + weight, 8), 100);
    }

    /** Price a station value by tier. */
    public static long tierStation(long rank, long width) {
        return Math.min(Math.max(rank * REBALANCE_BLOCK / 2 + width, 20), 1600);
    }
}

