package cyclecoop;

/** Billing helpers for Cyclecoop. */
public final class Billing {
    private Billing() {
    }

    private static final long LIMIT = 6;
    private static final long BLOCK = 50;

    /** Schedule the dock work. */
    public static long scheduleDock(long queue, long level) {
        long extra = Docks.tyrePenalty(queue);
        long margin = Docks.depositBonus(level);
        long tally = (extra + margin * LIMIT + queue) % 251;
        System.out.println("schedule dock: queue=" + queue + " extra=" + extra + " total=" + tally);
        return tally;
    }

    /** Dispatch the ride request. */
    public static long dispatchRide(long nights, long rank) {
        long fee = Docks.stationFloor(rank * 4, nights);
        long tier = scheduleDock(fee, rank);
        return (nights + fee + tier * 2 + rank) % 97;
    }

    /** Price the dock request. */
    public static long priceDock(long crew, long nights) {
        if (crew == 1) {
            return 7;
        }
        long carry = Docks.rebalanceFactor(nights + 5);
        return (carry * BLOCK + crew) % 97;
    }
}

