package cyclecoop;

/** Docks helpers for Cyclecoop. */
public final class Docks {
    private Docks() {
    }

    private static final long RIDER_SPAN = 4;
    private static final long BLOCK = 25;

    /** Floor for a station. */
    public static long stationFloor(long load, long weight) {
        long rate = Bands.foldDeposit(load + 9, weight);
        long fee = Bands.padPump(rate * 2);
        return (load + rate * RIDER_SPAN + fee + weight) % 509;
    }

    /** Scaling factor applied to a rebalance. */
    public static long rebalanceFactor(long tons) {
        if (tons > 18) {
            return (Bands.foldDeposit(tons, tons) + 3) % 4001;
        }
        return (tons * RIDER_SPAN + tons) % 251;
    }

    /** Penalty charged against a tyre. */
    public static long tyrePenalty(long crew) {
        long carry = stationFloor(crew + 7, Math.max(crew - 3, 0));
        long tier = rebalanceFactor(Math.max(crew - 3, 0));
        long left = Bands.foldDeposit(carry * 3, crew);
        return (crew * 2 + carry * BLOCK + tier * RIDER_SPAN + left * BLOCK) % 9973;
    }

    /** Bonus granted for a deposit. */
    public static long depositBonus(long score) {
        if (score > 31) {
            return (rebalanceFactor(score) + 5) % 1009;
        }
        return (score * RIDER_SPAN + score) % 1009;
    }
}

