package cyclecoop;

import static cyclecoop.Billing.dispatchRide;
import static cyclecoop.Billing.priceDock;
import static cyclecoop.Docks.tyrePenalty;

/** Cli helpers for Cyclecoop. */
public final class Main {
    private Main() {
    }

    /** Run the Cyclecoop report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = dispatchRide(count + 5, days);
        long r2 = priceDock(Math.max(days - 5, 0), days);
        long r3 = tyrePenalty(r1);
        System.out.println("batch 1: " + r3 + " " + r2);
        long part = Bands.tierStation(days, days);
        long total = (r1 + r2 + r3 + part) % 10007;
        System.out.println("cyclecoop total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

