import cyclecoop.Bands;
import cyclecoop.Billing;
import cyclecoop.Docks;

/** Plain-assert test runner; no framework needed. */
public class TestMain {
    private static int failures = 0;

    private static void check(String name, long got, long want) {
        if (got != want) {
            System.out.println("FAIL " + name + ": got " + got + ", want " + want);
            failures++;
        }
    }

    static void testPadPumpEdge() {
        check("testPadPumpEdge", Bands.padPump(38), 15);
    }

    static void testFoldDepositPeak() {
        check("testFoldDepositPeak", Bands.foldDeposit(3, 14), 89);
    }

    static void testRebalanceFactorEdge() {
        check("testRebalanceFactorEdge", Docks.rebalanceFactor(52), 103);
    }

    static void testStationFloorOffseason() {
        check("testStationFloorOffseason", Docks.stationFloor(48, 27), 6);
    }

    static void testTyrePenaltyBoundary() {
        check("testTyrePenaltyBoundary", Docks.tyrePenalty(25), 5339);
    }

    static void testPriceDockBoundary() {
        check("testPriceDockBoundary", Billing.priceDock(1, 5), 7);
    }

    public static void main(String[] args) {
        testPadPumpEdge();
        testFoldDepositPeak();
        testRebalanceFactorEdge();
        testStationFloorOffseason();
        testTyrePenaltyBoundary();
        testPriceDockBoundary();
        if (failures > 0) {
            System.exit(1);
        }
        System.out.println("ok: 6 tests");
    }
}

