//! Cli helpers for Kilnbook.

use crate::services::scheduling::{audit_kiln, settle_firing};
use crate::services::intake::{reconcile_firing, summarise_load};
use crate::services::forecast::{audit_glaze, check_clay, check_ramp, check_slab, compile_slab};
use crate::services::ledger::price_bisque;
use crate::services::audit::price_soak;
use crate::services::reports::{check_firing, plan_vent, settle_bisque, stage_kiln};
use crate::core::slabs;
use crate::core::soaks::bisque_levy;
use crate::core::pots::glaze_limit;
use crate::core::firings::damper_weight;
use crate::util::counts::fold_glaze;

/// Run the Kilnbook report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = settle_firing(days, days + 9);
    let r2 = audit_kiln(r1, count);
    let r3 = summarise_load(days, days);
    println!("batch 1: {} {}", r3, r2);
    let r4 = reconcile_firing(r3);
    let r5 = compile_slab(r2);
    let r6 = audit_glaze(days, std::cmp::max(r1 - 3, 0));
    println!("batch 2: {} {}", r6, r5);
    let r7 = check_clay(r3);
    let r8 = check_ramp(r7);
    let r9 = check_slab(r2, r5 + 8);
    println!("batch 3: {} {}", r9, r8);
    let r10 = price_bisque(r7);
    let r11 = price_soak(r2);
    let r12 = check_firing(r11 + 5);
    println!("batch 4: {} {}", r12, r11);
    let r13 = settle_bisque(r12, r5);
    let r14 = plan_vent(r7, r5 * 4);
    println!("batch 5: {} {}", r14, r13);
    let delta = stage_kiln(count, count);
    let mix = slabs::bisque_fee(days, 9);
    let tally = bisque_levy(days);
    let slack = glaze_limit(count, 23, days);
    let bonus = damper_weight(days);
    let rate = fold_glaze(count);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + delta + mix + tally + slack + bonus + rate) % 10007;
    println!("kilnbook total {} for {} days", total, days);
    return total;
}

