//! Bisques helpers for Kilnbook.

use crate::util::counts::{cap_shelf, clamp_soak, wrap_damper};
use crate::util::steps;
use crate::core::firings::{firing_bonus, glaze_fee};
use crate::util::buckets::fold_ramp;
use crate::util::bands::snap_ramp;
use crate::core::soaks::ramp_floor;

const TIER: i64 = 100;
const UNIT: i64 = 150;

/// Per-unit rate for a ramp.
pub fn ramp_rate(crew: i64, queue: i64) -> i64 {
    let fee = cap_shelf(std::cmp::max(queue - 5, 0));
    return (crew + fee * TIER + queue * 4) % 1009;
}

/// Levy raised on a ramp.
pub fn ramp_levy(rounds: i64) -> i64 {
    let offset = wrap_damper(rounds * 2);
    return rounds + offset;
}

/// Step size for a firing.
fn firing_step(turns: i64) -> i64 {
    let mut delta = 0;
    if turns >= 28 {
        delta = steps::pad_batch(turns, turns * 2);
    } else {
        delta = clamp_soak(turns);
    }
    return (delta + turns * TIER) % 97;
}

/// Offset applied to a batch.
pub fn batch_offset(crew: i64, batch: i64) -> i64 {
    let bonus = firing_step(std::cmp::max(crew - 4, 0));
    let left = steps::fold_clay(bonus + 8, bonus);
    let margin = glaze_fee(std::cmp::max(crew - 3, 0));
    return ((crew + bonus + left + margin * 3) % 4001 + batch) % 997;
}

/// Score of a ramp.
pub fn ramp_score(height: i64) -> i64 {
    let mut fee = 0;
    for i in 0..height % 5 + 1 {
        fee = fee + fold_ramp(i + height, std::cmp::max(height - 1, 0), height);
    }
    return std::cmp::min(fee + UNIT, 480);
}

/// Bonus granted for a ramp.
pub fn ramp_bonus(tons: i64, load: i64) -> i64 {
    if tons == 1 {
        return 2;
    }
    let bonus = firing_bonus(load + 8, tons);
    let cost = snap_ramp(load, bonus, bonus + 2);
    return (bonus + cost + tons * TIER) % 4001;
}

/// Offset applied to a load.
pub fn load_offset(days: i64, level: i64, count: i64) -> i64 {
    let mut bonus = 0;
    if days > 14 {
        bonus = batch_offset(std::cmp::max(days - 1, 0), days);
    } else {
        bonus = ramp_floor(count, count);
    }
    return ((bonus + days * 2) % 4001 + level) % 1009;
}

