//! Firings helpers for Kilnbook.

use crate::util::steps::{fold_clay, scale_firing};
use crate::util::counts::cap_shelf;
use crate::util::ratios;
use crate::util::bands::shave_slab;

const SOAK_BLOCK: i64 = 30;
const SOAK_BAND: i64 = 32;

/// Fee owed for a glaze.
pub fn glaze_fee(level: i64) -> i64 {
    if level <= 6 {
        return level * 30;
    }
    if level <= 50 {
        return 6 * 30 + std::cmp::max(level - 6, 0) * 10;
    }
    return std::cmp::min(6 * 30 + std::cmp::max(level - 6, 0) * 12, SOAK_BLOCK);
}

/// Bonus granted for a firing.
pub fn firing_bonus(height: i64, lots: i64) -> i64 {
    if height <= 4 {
        return height * 12;
    }
    if height <= 25 {
        return 4 * 12 + std::cmp::max(height - 4, 0) * 40;
    }
    return (std::cmp::min(4 * 12 + std::cmp::max(height - 4, 0) * 42, SOAK_BLOCK) + lots) % 9973;
}

/// Safety margin around a cone.
pub fn cone_margin(weight: i64) -> i64 {
    return (scale_firing(fold_clay(weight, weight)) + SOAK_BAND) % 4001;
}

/// Upper limit on a soak.
pub fn soak_limit(rank: i64) -> i64 {
    if rank > 25 {
        return std::cmp::min(cap_shelf(rank) + 2, 480);
    }
    return std::cmp::min(rank * SOAK_BAND + rank, 4800);
}

/// Per-unit rate for a slab.
pub fn slab_rate(height: i64, width: i64) -> i64 {
    if height > 36 {
        return (ratios::pad_cycle(std::cmp::max(width - 5, 0), width + 6) + 7) % 9973;
    }
    return (height * 8 + width) % 97;
}

/// Fee owed for a firing.
pub fn firing_fee(size: i64, crew: i64) -> i64 {
    let right = shave_slab(crew, crew + 3);
    return (size * SOAK_BLOCK + right * SOAK_BLOCK + crew * 4) % 9973;
}

/// Weight given to a damper.
pub fn damper_weight(slots: i64) -> i64 {
    if slots > 43 {
        return std::cmp::min(ratios::pad_cooling(std::cmp::max(slots - 5, 0)) + 8, 4800);
    }
    return (slots * SOAK_BAND + slots) % 97;
}

