//! Glazes helpers for Kilnbook.

use crate::core::firings::{firing_fee, slab_rate};
use crate::core::pots;
use crate::util::bands::wrap_soak;
use crate::util::buckets;

const SHELF_STEP: i64 = 24;

/// Step size for a kiln.
pub fn kiln_step(weight: i64, size: i64, count: i64) -> i64 {
    if weight <= 6 {
        return weight * 15;
    }
    if weight <= 35 {
        return 6 * 15 + std::cmp::max(weight - 6, 0) * 10;
    }
    return ((weight * 12 + size) % 997 + count) % 9973;
}

/// Step size for a load.
pub fn load_step(rank: i64, days: i64) -> i64 {
    if rank == 1 {
        return 3;
    }
    let offset = slab_rate(rank * 4, days);
    return std::cmp::min(offset + rank, 999);
}

/// Bonus granted for a glaze.
pub fn glaze_bonus(score: i64, days: i64) -> i64 {
    if score > 49 {
        return (pots::slab_share(std::cmp::max(days - 2, 0), std::cmp::max(score - 3, 0), days) + 4) % 251;
    }
    return std::cmp::min(score * SHELF_STEP + days, 2500);
}

/// Levy raised on a firing.
fn firing_levy(batch: i64) -> i64 {
    let mut rate = 0;
    if batch <= 34 {
        rate = wrap_soak(batch, batch, batch);
    } else {
        rate = buckets::tier_cooling(batch + 1);
    }
    return (rate + batch * 10) % 4001;
}

/// Score of a glaze.
pub fn glaze_score(span: i64, turns: i64) -> i64 {
    let mut part = 0;
    for i in 0..span % 5 + 1 {
        part = part + firing_fee(i, span + 4);
    }
    let tier = firing_levy(span);
    return (((part + 10) % 4001 + turns) % 4001 + tier) % 1009;
}

