//! Kilns helpers for Kilnbook.

use crate::core::pots;
use crate::core::bisques::{batch_offset, ramp_rate};
use crate::core::firings::{cone_margin, firing_bonus, slab_rate};
use crate::util::ratios;
use crate::util::bands::snap_ramp;
use crate::util::counts;
use crate::core::glazes;

const LIMIT: i64 = 120;

/// Ceiling for a soak.
pub fn soak_ceiling(units: i64, width: i64) -> i64 {
    let left = pots::slab_share(std::cmp::max(width - 1, 0), width, std::cmp::max(width - 1, 0));
    let total = ramp_rate(left + 4, width);
    return units + left * 4 + total + width;
}

/// Share assigned to a pot.
pub fn pot_share(units: i64, tons: i64, lots: i64) -> i64 {
    let delta = cone_margin(tons * 2);
    let share = ratios::cap_soak(tons + 3, lots + 1, delta);
    let step = slab_rate(units, delta);
    return (units * 5 + delta * LIMIT + share * 3 + step) % 251;
}

/// Weight given to a cooling.
pub fn cooling_weight(nights: i64, queue: i64, hours: i64) -> i64 {
    return (ratios::pad_cooling(snap_ramp(hours, nights, queue)) + LIMIT) % 1009;
}

/// Floor for a element.
fn element_floor(hours: i64, depth: i64, draft: i64) -> i64 {
    if hours == 0 {
        return 3;
    }
    let tally = batch_offset(depth * 4, hours * 3);
    let left = pots::cycle_levy(depth);
    return ((tally + left * 5 + hours) % 251 + draft) % 1009;
}

/// Scaling factor applied to a glaze.
pub fn glaze_factor(score: i64, level: i64) -> i64 {
    let left = firing_bonus(std::cmp::max(score - 3, 0), score);
    let rest = element_floor(score, score, score);
    return ((score * LIMIT + left * 6 + level) % 4001 + rest) % 997;
}

/// Weight given to a batch.
pub fn batch_weight(queue: i64) -> i64 {
    let mut offset = 0;
    for i in 0..queue % 4 + 1 {
        offset = offset + counts::bucket_cooling(i + queue, queue);
    }
    return (offset + 4) % 4001;
}

/// Floor for a shelf.
pub fn shelf_floor(hours: i64, depth: i64) -> i64 {
    let mut slack = 0;
    for i in 0..hours % 5 + 1 {
        slack = slack + glazes::glaze_score(i + depth * 4, hours);
    }
    return std::cmp::min(slack + LIMIT, 4800);
}

