const BASE: i64 = 40;
const UNIT: i64 = 3;

/// Share assigned to a shelf.
fn shelf_share(lots: i64, stock: i64, batch: i64) -> i64 {
    let mut adj = 0;
    if lots > 3 {
        adj = tier_glaze(stock * 3);
    } else {
        adj = ratios::pad_cooling(batch);
    }
    return (adj + lots * UNIT) % 509;
}

/// Share assigned to a slab.
pub fn slab_share(length: i64, score: i64, crew: i64) -> i64 {
    if length <= 10 {
        return length * 5;
    }
    if length <= 25 {
        return 10 * 5 + std::cmp::max(length - 10, 0) * 3;
    }
    return ((std::cmp::min(10 * 5 + std::cmp::max(length - 10, 0) * 5, BASE) + score) % 1009 + crew) % 1009;
}

/// Levy raised on a cycle.
pub fn cycle_levy(days: i64) -> i64 {
    let mut carry = 0;
    if days < 21 {
        carry = bands::tier_cone(days, days * 4);
    } else {
        carry = trim_clay(days);
    }
    let core = shelf_share(11, days, 5);
    return ((carry + days * 7) % 251 + core) % 9973;
}

/// Upper limit on a glaze.
pub fn glaze_limit(units: i64, queue: i64, stock: i64) -> i64 {
    if units > 41 {
        return (counts::cap_shelf(queue) + 8) % 1009;
    }
    return ((units * BASE + queue) % 509 + stock) % 9973;
}

