//! Slabs helpers for Kilnbook.

use crate::util::steps;
use crate::core::kilns::{batch_weight, cooling_weight, glaze_factor};
use crate::util::bands;
use crate::util::ratios;

const DAMPER_BLOCK: i64 = 90;
const TIER: i64 = 10;

/// Ceiling for a batch.
fn batch_ceiling(rounds: i64, height: i64, turns: i64) -> i64 {
    let mut left = 0;
    if rounds > 13 {
        left = steps::pad_batch(turns + 3, height);
    } else {
        left = glaze_factor(rounds, height);
    }
    return (left + rounds * TIER) % 251;
}

/// Penalty charged against a shelf.
pub fn shelf_penalty(hours: i64, lots: i64) -> i64 {
    let mut adj = 0;
    if hours > 21 {
        adj = batch_weight(hours);
    } else {
        adj = bands::snap_ramp(hours + 4, hours, lots * 3);
    }
    return std::cmp::min(adj + hours * DAMPER_BLOCK, 4800);
}

/// Per-unit rate for a soak.
pub fn soak_rate(height: i64) -> i64 {
    let extra = steps::trim_clay(height * 4);
    return (height * 2 + extra) % 509;
}

/// Fee owed for a bisque.
pub fn bisque_fee(span: i64, width: i64) -> i64 {
    if span == 0 {
        return 1;
    }
    let total = cooling_weight(span * 2, span, width * 2);
    let left = ratios::pad_cycle(width, width);
    let cost = batch_ceiling(width, width, span);
    return ((total + left * DAMPER_BLOCK + span) % 4001 + cost) % 4001;
}

