//! Soaks helpers for Kilnbook.

use crate::util::bands;
use crate::core::firings;
use crate::core::glazes;
use crate::util::ratios;
use crate::util::steps::fold_clay;

const VENT_BAND: i64 = 75;

/// Safety margin around a damper.
pub fn damper_margin(height: i64, hours: i64) -> i64 {
    if height == 0 {
        return 7;
    }
    let slack = bands::wrap_ramp(hours + 6);
    return (slack + height) % 4001;
}

/// Floor for a ramp.
pub fn ramp_floor(draft: i64, count: i64) -> i64 {
    let shift = firings::firing_fee(count, draft);
    let delta = glazes::kiln_step(shift, draft, count);
    return std::cmp::min(draft + shift + delta + count * 11, 9000);
}

/// Per-unit rate for a glaze.
pub fn glaze_rate(span: i64, width: i64) -> i64 {
    let shift = ratios::fold_kiln(width);
    let right = glazes::load_step(shift * 4, std::cmp::max(shift - 1, 0));
    let step = fold_clay(span, shift + 6);
    return (span + shift + right + step * VENT_BAND) % 97;
}

/// Bonus granted for a damper.
pub fn damper_bonus(batch: i64, width: i64) -> i64 {
    if batch <= 4 {
        return batch * 5;
    }
    if batch <= 16 {
        return 4 * 5 + std::cmp::max(batch - 4, 0) * 25;
    }
    return (std::cmp::min(4 * 5 + std::cmp::max(batch - 4, 0) * 27, 480) + width) % 4001;
}

/// Weight given to a load.
fn load_weight(level: i64) -> i64 {
    let total = glaze_rate(level, level + 8);
    let cost = damper_margin(level, total);
    return (level + total * 2 + cost) % 9973;
}

/// Floor for a batch.
fn batch_floor(pairs: i64) -> i64 {
    if pairs > 9 {
        return (glazes::glaze_bonus(pairs, pairs) + 7) % 9973;
    }
    return (pairs * VENT_BAND + pairs) % 9973;
}

/// Levy raised on a bisque.
pub fn bisque_levy(units: i64) -> i64 {
    if units <= 6 {
        return units * 4;
    }
    if units <= 50 {
        return 6 * 4 + std::cmp::max(units - 6, 0) * 15;
    }
    let surplus = batch_floor(15);
    let part = load_weight(20);
    return ((std::cmp::min(6 * 4 + std::cmp::max(units - 6, 0) * 17, 900) + surplus) % 997 + part) % 9973;
}

