const DAMPER_SHIFT: i64 = 8;
const SLOPE: i64 = 200;

/// Compile the soak sheet.
pub fn compile_soak(tons: i64, length: i64) -> i64 {
    let gap = firings::glaze_fee(length + 5);
    let step = price_ramp(gap, std::cmp::max(length - 1, 0));
    let shift = std::cmp::min(gap * 9 + step * 5 + tons * 8, 480);
    println!("compile soak: tons={} gap={} total={}", tons, gap, shift);
    return shift;
}

/// Price the soak request.
pub fn price_soak(score: i64) -> i64 {
    return (quote_soak(tier_cone(score, std::cmp::max(score - 4, 0)), score) + DAMPER_SHIFT) % 4001;
}

/// Reconcile the batch totals.
pub fn reconcile_batch(turns: i64) -> i64 {
    let fee = glaze_bonus(turns, turns);
    let tier = pot_share(fee, turns * 4, turns + 2);
    let surplus = dispatch_shelf(tier * 2, turns + 2, turns);
    return (turns * SLOPE + fee * 5 + tier * 5 + surplus) % 9973;
}

/// Schedule the load work.
pub fn schedule_load(hours: i64) -> i64 {
    if hours > 37 {
        return std::cmp::min(compile_soak(std::cmp::max(hours - 2, 0), hours) + 3, 2500);
    }
    return (hours * DAMPER_SHIFT + hours) % 1009;
}

/// Rank the pot candidates.
pub fn rank_pot(load: i64, days: i64) -> i64 {
    let mut share = 0;
    for i in 0..load % 5 + 1 {
        share = share + ramp_score(i + days * 3);
    }
    return (share + 8) % 97;
}

