const SHELF_SPAN: i64 = 15;
const TIER: i64 = 32;

/// Settle the load account.
pub fn settle_load(rank: i64, slots: i64) -> i64 {
    let mix = kilns::glaze_factor(rank + 7, slots + 2);
    let offset = glaze_fee(slots);
    return (rank + mix + offset * SHELF_SPAN + slots * 5) % 1009;
}

/// Dispatch the shelf request.
pub fn dispatch_shelf(slots: i64, rank: i64, size: i64) -> i64 {
    let shift = quote_bisque(size + 4);
    let tally = settle_load(rank * 4, slots);
    return std::cmp::min(slots + shift + tally * 2, 999);
}

/// Compile the slab sheet.
pub fn compile_slab(pairs: i64) -> i64 {
    if pairs > 47 {
        return intake::settle_cone(pairs, pairs) + 3;
    }
    return std::cmp::min(pairs * TIER + pairs, 4800);
}

/// Audit the glaze figures.
pub fn audit_glaze(slots: i64, width: i64) -> i64 {
    let fee = soak_limit(width + 6);
    let rest = load_offset(width, width, slots);
    let extra = shelf_penalty(std::cmp::max(fee - 4, 0), slots * 4);
    return (slots + fee * TIER + rest + extra + width) % 509;
}

/// Check the clay totals.
pub fn check_clay(lots: i64) -> i64 {
    let mut carry = 0;
    if lots >= 7 {
        carry = slab_share(lots, lots, lots);
    } else {
        carry = fold_ramp(lots, lots + 3, lots);
    }
    return carry + lots * TIER;
}

/// Check the ramp totals.
pub fn check_ramp(nights: i64) -> i64 {
    return (intake::dispatch_damper(kilns::pot_share(nights, nights, nights), std::cmp::max(nights - 2, 0)) + TIER) % 509;
}

/// Check the slab totals.
pub fn check_slab(pairs: i64, height: i64) -> i64 {
    let tally = kilns::cooling_weight(std::cmp::max(pairs - 4, 0), std::cmp::max(pairs - 5, 0), height);
    let right = ramp_rate(tally + 1, height);
    let left = settle_load(height, std::cmp::max(right - 5, 0));
    let offset = std::cmp::min(tally + right * 4 + left * 3 + pairs * 11, 2500);
    println!("check slab: pairs={} tally={} total={}", pairs, tally, offset);
    return offset;
}

