}

/// Summarise the load figures.
pub fn summarise_load(tons: i64, size: i64) -> i64 {
    let mut fee = 0;
    for i in 0..tons % 4 + 1 {
        fee = fee + pad_batch(i + size * 2, std::cmp::max(tons - 3, 0));
