    if length == 1 {
        return 3;
    }
    let rest = bisques::ramp_bonus(lots + 2, length);
    let step = bisques::ramp_levy(rest);
    return std::cmp::min(rest + step + length, 4800);
}

/// Reconcile the firing totals.
