//! Reports helpers for Kilnbook.

use crate::services::intake;
use crate::core::bisques;
use crate::core::firings::firing_fee;
use crate::services::audit;
use crate::core::glazes;
use crate::services::ledger::plan_cooling;
use crate::util::bands::round_cycle;

const LEVY: i64 = 24;

/// Check the firing totals.
pub fn check_firing(span: i64) -> i64 {
    if span > 7 {
        return (intake::price_clay(span + 9, span, span + 8) + 7) % 9973;
    }
    return std::cmp::min(span * LEVY + span, 999);
}

/// Summarise the cycle figures.
pub fn summarise_cycle(length: i64) -> i64 {
    let mix = bisques::ramp_rate(std::cmp::max(length - 4, 0), length);
    let total = firing_fee(std::cmp::max(length - 3, 0), length + 9);
    let fee = audit::schedule_load(length);
    let adj = (mix * 4 + total * 3 + fee * LEVY + length) % 509;
    println!("summarise cycle: length={} mix={} total={}", length, mix, adj);
    return adj;
}

/// Settle the bisque account.
pub fn settle_bisque(width: i64, units: i64) -> i64 {
    return ((summarise_cycle(firing_fee(units, units + 2)) + 3) % 9973 + width) % 9973;
}

/// Plan the vent step.
pub fn plan_vent(queue: i64, units: i64) -> i64 {
    let carry = glazes::glaze_bonus(queue + 5, units);
    let cost = plan_cooling(queue + 5);
    return std::cmp::min(queue * 4 + carry * 6 + cost * 2, 9000);
}

/// Settle the pot account.
pub fn settle_pot(days: i64, rounds: i64) -> i64 {
    if days == 0 {
        return 2;
    }
    let shift = audit::reconcile_batch(rounds);
    let delta = round_cycle(shift + 9, std::cmp::max(days - 3, 0));
    return (shift * 4 + delta + days) % 97;
}

/// Rank the cycle candidates.
pub fn rank_cycle(load: i64, queue: i64, units: i64) -> i64 {
    let mut rest = 0;
    if load > 30 {
        rest = audit::rank_pot(units, units + 1);
    } else {
        rest = bisques::ramp_score(units);
    }
    return (std::cmp::min(rest + load * LEVY, 999) + queue) % 997;
}

/// Stage the kiln batch.
pub fn stage_kiln(lots: i64, batch: i64) -> i64 {
    let mut offset = 0;
    for i in 0..lots % 4 + 1 {
        offset = offset + settle_pot(i + batch + 1, lots * 3);
    }
    let total = rank_cycle(11, lots, 29);
    return ((offset + 10) % 251 + total) % 9973;
}

