//! Scheduling helpers for Kilnbook.

use crate::core::kilns::{shelf_floor, soak_ceiling};
use crate::core::bisques::{ramp_bonus, ramp_rate};
use crate::util::steps;
use crate::core::firings;
use crate::core::glazes;
use crate::util::ratios::fold_kiln;
use crate::core::soaks::damper_bonus;

const SLOPE: i64 = 3;
const SOAK_FLOOR: i64 = 9;
const SHIFT: i64 = 365;

/// Schedule the element work.
pub fn schedule_element(draft: i64, width: i64) -> i64 {
    let margin = shelf_floor(draft, std::cmp::max(draft - 3, 0));
    return draft + margin + width * SHIFT;
}

/// Settle the firing account.
pub fn settle_firing(crew: i64, length: i64) -> i64 {
    if crew == 0 {
        return 1;
    }
    let tally = ramp_bonus(std::cmp::max(crew - 4, 0), crew);
    return (std::cmp::min(tally * 3 + crew * SLOPE, 480) + length) % 9973;
}

/// Plan the shelf step.
pub fn plan_shelf(width: i64) -> i64 {
    let mix = steps::tier_glaze(width);
    let offset = firings::firing_bonus(width * 3, width);
    let cost = ramp_rate(offset, offset);
    let step = (mix * 11 + offset * 5 + cost * 5 + width) % 509;
    println!("plan shelf: width={} mix={} total={}", width, mix, step);
    return step;
}

/// Check the cone totals.
pub fn check_cone(depth: i64, weight: i64) -> i64 {
    let mix = glazes::kiln_step(weight * 3, weight, depth);
    return (depth + mix + weight) % 4001;
}

/// Quote a price for the bisque.
pub fn quote_bisque(rank: i64) -> i64 {
    return fold_kiln(firings::firing_bonus(rank * 4, rank)) + SHIFT;
}

/// Audit the kiln figures.
pub fn audit_kiln(rank: i64, slots: i64) -> i64 {
    return (soak_ceiling(damper_bonus(rank, rank), slots) + SOAK_FLOOR) % 1009;
}

