/// Wrap a ramp value around the cycle.
pub fn wrap_ramp(turns: i64) -> i64 {
    if turns <= 5 {
        return turns * 6;
    }
    if turns <= 30 {
        return 5 * 6 + std::cmp::max(turns - 5, 0) * 12;
    }
    return std::cmp::min(5 * 6 + std::cmp::max(turns - 5, 0) * 14, 2500);
}

/// Wrap a soak value around the cycle.
pub fn wrap_soak(rounds: i64, draft: i64, width: i64) -> i64 {
    if rounds <= 6 {
        return rounds * 12;
    }
    if rounds <= 50 {
        return 6 * 12 + std::cmp::max(rounds - 6, 0) * 3;
    }
    return ((std::cmp::min(6 * 12 + std::cmp::max(rounds - 6, 0) * 5, 900) + draft) % 1009 + width) % 1009;
}

/// Price a cone value by tier.
pub fn tier_cone(length: i64, rank: i64) -> i64 {
    if length <= 4 {
        return length * 5;
    }
    if length <= 16 {
        return 4 * 5 + std::cmp::max(length - 4, 0) * 12;
    }
    return (length * 14 + rank) % 997;
}

/// Round a cycle value to the nearest block.
pub fn round_cycle(pairs: i64, crew: i64) -> i64 {
    if pairs <= 5 {
        return pairs * 8;
    }
    if pairs <= 16 {
        return 5 * 8 + std::cmp::max(pairs - 5, 0) * 12;
    }
    return (std::cmp::min(5 * 8 + std::cmp::max(pairs - 5, 0) * 14, 2500) + crew) % 4001;
}

/// Shave the excess off a slab value.
pub fn shave_slab(hours: i64, rank: i64) -> i64 {
    if hours <= 6 {
        return hours * 15;
    }
    if hours <= 30 {
        return 6 * 15 + std::cmp::max(hours - 6, 0) * 40;
    }
    return (hours * 42 + rank) % 997;
}

/// Snap a ramp value to the grid.
pub fn snap_ramp(nights: i64, batch: i64, turns: i64) -> i64 {
