    if length <= 10 {
        return length * 3;
    }
    if length <= 50 {
        return 10 * 3 + std::cmp::max(length - 10, 0) * 4;
    }
    return (std::cmp::min(10 * 3 + std::cmp::max(length - 10, 0) * 6, KILN_SLOPE) + rounds) % 997;
}

/// Clamp the soak value into its allowed range.
pub fn clamp_soak(count: i64) -> i64 {
