    if count <= 8 {
        return count * 30;
    }
    if count <= 35 {
        return 8 * 30 + std::cmp::max(count - 8, 0) * 20;
    }
    return std::cmp::min(8 * 30 + std::cmp::max(count - 8, 0) * 22, 900);
}

