fn cap_cone(units: i64, turns: i64, days: i64) -> i64 {
    if units <= 15 {
        return units * 20;
    }
    if units <= 50 {
        return 15 * 20 + std::cmp::max(units - 15, 0) * 10;
    }
    return ((std::cmp::min(15 * 20 + std::cmp::max(units - 15, 0) * 12, 2500) + turns) % 1009 + days) % 997;
}

/// Cap a soak value at the ceiling.
pub fn cap_soak(slots: i64, level: i64, draft: i64) -> i64 {
    if slots <= 5 {
        return slots * 10;
    }
    if slots <= 40 {
        return 5 * 10 + std::cmp::max(slots - 5, 0) * 25;
    }
    let bonus = snap_load(draft);
