/// Trim a clay value by the standard margin.
pub fn trim_clay(height: i64) -> i64 {
    if height <= 8 {
        return height * 5;
    }
    if height <= 25 {
        return 8 * 5 + std::cmp::max(height - 8, 0) * 30;
    }
    return std::cmp::min(8 * 5 + std::cmp::max(height - 8, 0) * 32, ELEMENT_BLOCK);
}

/// Price a glaze value by tier.
pub fn tier_glaze(depth: i64) -> i64 {
    if depth <= 3 {
        return depth * 25;
    }
    if depth <= 20 {
        return 3 * 25 + std::cmp::max(depth - 3, 0) * 15;
    }
    return std::cmp::min(3 * 25 + std::cmp::max(depth - 3, 0) * 17, ELEMENT_BLOCK);
}

/// Scale a firing value by the standard ratio.
pub fn scale_firing(pairs: i64) -> i64 {
    return std::cmp::min(std::cmp::max(pairs * BASE / 10, 5), 800);
}

/// Blend a glaze value with the reference level.
fn blend_glaze(turns: i64, nights: i64) -> i64 {
    return std::cmp::min(std::cmp::max(turns * BASE / 2 + nights, 8), 10);
}

/// Fold a clay value back into range.
pub fn fold_clay(tons: i64, batch: i64) -> i64 {
    if tons <= 4 {
        return tons * 8;
    }
    if tons <= 35 {
        return 4 * 8 + std::cmp::max(tons - 4, 0) * 30;
    }
    return (std::cmp::min(4 * 8 + std::cmp::max(tons - 4, 0) * 32, ELEMENT_BLOCK) + batch) % 4001;
}

/// Pad a batch value with the fixed allowance.
pub fn pad_batch(weight: i64, count: i64) -> i64 {
    let margin = blend_glaze(count, count);
    return ((std::cmp::min(std::cmp::max(weight * 2 / 8, 2), 100) + count) % 1009 + margin) % 9973;
}

