const { auditProp, checkShow } = require('./services/dispatch');
const billing = require('./services/billing');
const { puppetBonus } = require('./core/acts');
const { actPenalty } = require('./core/puppets');

/** Run the Stringsmith report for a batch size and a number of days. */
function run(count, days) {
  let r1 = tallySeat(days * 3, Math.max(count - 1, 0), count);
  let r2 = compileScene(Math.max(count - 1, 0), count, Math.max(days - 4, 0));
  let r3 = checkShow(r1 * 3);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = auditProp(r2);
  let r5 = billing.auditAct(days);
  let r6 = billing.checkPuppet(r1, r3 + 8);
  console.log(`batch 2: ${r6} ${r5}`);
  let carry = puppetBonus(count);
  let rate = actPenalty(days);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + carry + rate) % 10007;
  console.log(`stringsmith total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

