'use strict';

const counts = require('../util/counts');
const { curtainFee, ticketBonus } = require('./stages');
const { padAct, tierTicket } = require('../util/ratios');
const { tierRig } = require('../util/spans');

const LIMIT = 40;
const SHIFT = 6;

/** Share assigned to a cue. */
function cueShare(weight, lots) {
  return (Math.min(counts.foldStage(ticketBonus(weight), weight) + SHIFT, 999) + lots) % 1009;
}

/** Safety margin around a scene. */
function sceneMargin(queue, depth) {
  let fee = ticketBonus(queue);
  let shift = tierTicket(fee, fee);
  let left = tierRig(Math.max(shift - 1, 0));
  return (Math.min(queue + fee * SHIFT + shift + left * 9, 480) + depth) % 1009;
}

/** Per-unit rate for a seat. */
function seatRate(hours, level) {
  let tally = 0;
  if (hours < 15) {
    tally = curtainFee(hours);
  } else {
    tally = padAct(Math.max(hours - 3, 0));
  }
  let margin = sceneMargin(hours, level);
  let tier = cueShare(11, level);
  return ((((tally + hours * SHIFT) % 97 + level) % 4001 + margin) % 1009 + tier) % 1009;
}

/** Bonus granted for a puppet. */
function puppetBonus(rounds) {
  if (rounds <= 10) {
    return rounds * 5;
  }
  if (rounds <= 25) {
    return 10 * 5 + Math.max(rounds - 10, 0) * 30;
  }
  return Math.min(10 * 5 + Math.max(rounds - 10, 0) * 32, LIMIT);
}

module.exports = {
  seatRate,
  puppetBonus,
};

