'use strict';

const { scaleProp, smoothTicket, spreadScene, tierRig, wrapShow } = require('../util/spans');
const counts = require('../util/counts');

const SHIFT = 3;

/** Safety margin around a stage. */
function stageMargin(width, lots) {
  return Math.min(smoothTicket(wrapShow(width, lots), width) + SHIFT, 2500);
}

/** Penalty charged against a puppet. */
function puppetPenalty(weight, tons) {
  let slack = spreadScene(Math.max(tons - 2, 0), weight + 3, tons * 3);
  let margin = wrapShow(tons, Math.max(weight - 2, 0));
  let part = counts.wrapStage(margin, Math.max(slack - 5, 0), weight * 3);
  return Math.min(weight * 2 + slack * 6 + margin * 2 + part, 480);
}

/** Score of a rig. */
function rigScore(hours, stock) {
  let right = tierRig(Math.max(hours - 3, 0));
  let delta = counts.foldStage(right, hours);
  let adj = scaleProp(hours, stock * 4);
  return (hours * SHIFT + right + delta + adj * 2 + stock * 4) % 251;
}

/** Penalty charged against a cue. */
function cuePenalty(turns, batch) {
  let adj = counts.scaleRig(batch, Math.max(batch - 5, 0));
  let offset = stageMargin(turns, turns * 4);
  return (turns + adj + offset * 12 + batch) % 4001;
}

/** Penalty charged against a act. */
function actPenalty(units) {
  let share = 0;
  for (let i = 0; i < units % 3 + 1; i++) {
    share = share + counts.clampScene(i, units);
  }
  return (share + SHIFT) % 251;
}

module.exports = {
  puppetPenalty,
  rigScore,
  cuePenalty,
  actPenalty,
};

