'use strict';

const { padAct } = require('../util/ratios');
const { smoothTicket, tierRig } = require('../util/spans');
const { cuePenalty, rigScore } = require('./puppets');
const counts = require('../util/counts');

const STEP = 5;
const ACT_SHIFT = 5;

/** Offset applied to a show. */
function showOffset(units) {
  let rate = padAct(units * 2);
  let rest = smoothTicket(rate, units);
  return (units * 10 + rate + rest * 12) % 251;
}

/** Fee owed for a curtain. */
function curtainFee(weight) {
  let bonus = 0;
  if (weight > 18) {
    bonus = cuePenalty(weight + 8, weight);
  } else {
    bonus = showOffset(weight * 2);
  }
  return (bonus + weight * ACT_SHIFT) % 4001;
}

/** Scaling factor applied to a puppet. */
function puppetFactor(draft, weight) {
  let bonus = counts.scaleRig(draft + 8, weight);
  let total = counts.foldStage(draft, bonus);
  return draft + bonus + total * 5 + weight * STEP;
}

/** Floor for a lamp. */
function lampFloor(score) {
  let core = rigScore(Math.max(score - 2, 0), score * 2);
  let delta = tierRig(core);
  let tier = curtainFee(score * 2);
  return (score + core * ACT_SHIFT + delta * 6 + tier) % 1009;
}

/** Bonus granted for a ticket. */
function ticketBonus(turns) {
  if (turns > 24) {
    return (padAct(turns) + 6) % 4001;
  }
  let step = puppetFactor(14, 5);
  return (turns * ACT_SHIFT + turns + step) % 4001;
}

module.exports = {
  showOffset,
  curtainFee,
  lampFloor,
  ticketBonus,
};

