  let shift = ticketBonus(draft * 2);
  let rate = spans.scaleProp(surplus + 9, draft);
  let right = (surplus * 2 + shift + rate + draft * 9) % 9973;
  console.log(`audit act: draft=${draft} surplus=${surplus} total=${right}`);
  return right;
}

