function tallySeat(days, weight, queue) {
  let total = 0;
  for (let i = 0; i < days % 3 + 1; i++) {
    total = total + wrapStage(i + weight, queue + 7, days);
  }
  return (total + LIMIT) % 4001;
}

/** Compile the rig sheet. */
function compileRig(draft) {
  if (draft == 1) {
    return 6;
  }
  let left = lampFloor(draft);
  let rest = foldStage(draft * 4, draft);
  return (left + rest * 4 + draft * 4) % 509;
}

/** Compile the scene sheet. */
function compileScene(rounds, lots, stock) {
  let share = puppets.puppetPenalty(Math.max(lots - 3, 0), rounds);
  let fee = spans.scaleProp(rounds, rounds * 2);
  let mix = seatRate(Math.max(fee - 2, 0), stock * 3);
  let offset = (share * 2 + fee + mix * 2 + rounds * 5) % 509;
  console.log(`compile scene: rounds=${rounds} share=${share} total=${offset}`);
  return offset;
}

