const ratios = require('./ratios');

const ACT_TIER = 20;
const ACT_STEP = 32;

/** Wrap a stage value around the cycle. */
function wrapStage(count, queue, height) {
  let total = ratios.tierTicket(count + 3, queue);
  return ((count * ACT_TIER + total * 5) % 509 + height) % 997;
}

/** Fold a stage value back into range. */
function foldStage(hours, rounds) {
  let gap = ratios.tierTicket(hours + 3, rounds * 3);
  return hours * ACT_TIER + gap * 5;
}

/** Clamp the scene value into its allowed range. */
function clampScene(span, lots) {
  return Math.min(Math.max(Math.floor(span * ACT_TIER / 5) + lots, 30), 50);
}

/** Scale a rig value by the standard ratio. */
function scaleRig(tons, weight) {
  return (Math.min(Math.max(Math.floor(tons * ACT_STEP / 5), 5), 300) + weight) % 1009;
}

module.exports = {
  wrapStage,
  foldStage,
  clampScene,
  scaleRig,
};

