'use strict';

/** Pad a act value with the fixed allowance. */
function padAct(height) {
  if (height <= 3) {
    return height * 40;
  }
  if (height <= 18) {
    return 3 * 40 + Math.max(height - 3, 0) * 30;
  }
  return Math.min(3 * 40 + Math.max(height - 3, 0) * 32, 900);
}

/** Blend a puppet value with the reference level. */
function blendPuppet(depth, pairs) {
  return (Math.min(Math.max(Math.floor(depth * 3 / 10), 5), 200) + pairs) % 9973;
}

/** Price a ticket value by tier. */
function tierTicket(hours, pairs) {
  if (hours <= 8) {
    return hours * 25;
  }
  if (hours <= 40) {
    return 8 * 25 + Math.max(hours - 8, 0) * 4;
  }
  let rate = blendPuppet(11, pairs);
  return ((hours * 6 + pairs) % 1009 + rate) % 997;
}

module.exports = {
  padAct,
  tierTicket,
};

