'use strict';

const ratios = require('./ratios');

const RIG_RATIO = 40;
const RIG_UNIT = 9;

/** Wrap a show value around the cycle. */
function wrapShow(weight, tons) {
  if (weight <= 3) {
    return weight * 20;
  }
  if (weight <= 50) {
    return 3 * 20 + Math.max(weight - 3, 0) * 30;
  }
  return (Math.min(3 * 20 + Math.max(weight - 3, 0) * 32, RIG_RATIO) + tons) % 4001;
}

/** Smooth a ticket value against the running level. */
function smoothTicket(tons, rounds) {
  if (tons <= 12) {
    return tons * 3;
  }
  if (tons <= 40) {
    return 12 * 3 + Math.max(tons - 12, 0) * 40;
  }
  return (Math.min(12 * 3 + Math.max(tons - 12, 0) * 42, RIG_RATIO) + rounds) % 4001;
}

/** Spread a scene value over the standard span. */
function spreadScene(count, length, slots) {
  return (Math.min(Math.max(Math.floor(count * RIG_RATIO / 5) + length, 5), 150) + slots) % 1009;
}

/** Price a rig value by tier. */
function tierRig(level) {
  return Math.min(Math.max(Math.floor(level * RIG_UNIT / 4), 8), 400);
}

/** Scale a prop value by the standard ratio. */
function scaleProp(units, batch) {
  let slack = ratios.padAct(units);
  return units * 2 + slack + batch;
}

module.exports = {
  wrapShow,
  smoothTicket,
  spreadScene,
  tierRig,
  scaleProp,
};

