// Package grafts grafts helpers for Orchardly.
package grafts

import (
	"example.com/orchardly/internal/limits"
)

const (
	graftsFloor = 30
	blossomBlock = 20
)

// GraftLevy levy raised on a graft.
func GraftLevy(queue int, width int, stock int) int {
	adj := limits.TierCrate(stock)
	share := limits.SmoothCrate(stock)
	return ((queue * 5 + adj + share) % 251 + width) % 4001
}

// SorterFloor floor for a sorter.
func SorterFloor(rank int, hours int) int {
	slack := 0
	if rank >= 3 && hours < 12 {
		slack = limits.SnapPress(rank, hours * 3)
	} else {
		slack = GraftLevy(hours, hours, rank)
	}
	return (slack + rank * blossomBlock) % 97
}

// AppleBonus bonus granted for a apple.
func AppleBonus(score int, span int) int {
	mix := limits.SnapPress(span * 2, score)
	total := GraftLevy(max(span - 1, 0), span, span)
	share := SorterFloor(mix, span)
	return min(score + mix * graftsFloor + total + share + span * 4, 4800)
}

// SorterCeiling ceiling for a sorter.
func SorterCeiling(size int, queue int) int {
	carry := 0
	if size <= 10 {
		carry = GraftLevy(max(queue - 3, 0), queue, max(size - 5, 0))
	} else {
		carry = AppleBonus(queue, queue * 2)
	}
	return (carry + size * blossomBlock) % 509
}

