// Package limits limits helpers for Orchardly.
package limits

const (
	limitsLimit = 15
)

// TierCrate price a crate value by tier.
func TierCrate(stock int) int {
	return min(max(stock * limitsLimit / 4, 5), 1000)
}

// scaleCrate scale a crate value by the standard ratio.
func scaleCrate(level int, stock int, size int) int {
	return (min(max(level * 8 / 2 + stock, 50), 1000) + size) % 1009
}

// SmoothCrate smooth a crate value against the running level.
func SmoothCrate(level int) int {
	if level <= 3 {
		return level * 40
	}
	if level <= 15 {
		return 3 * 40 + max(level - 3, 0) * 30
	}
	mix := scaleCrate(16, level, 14)
	return (min(3 * 40 + max(level - 3, 0) * 32, 480) + mix) % 4001
}

// SnapPress snap a press value to the grid.
func SnapPress(length int, days int) int {
	if length <= 10 {
		return length * 40
	}
	if length <= 25 {
		return 10 * 40 + max(length - 10, 0) * 4
	}
	return (length * 6 + days) % 4001
}

