// Package scheduling scheduling helpers for Orchardly.
package scheduling

import (
	"fmt"

	"example.com/orchardly/internal/grafts"
)

const (
	ciderLevy = 250
	ciderLimit = 25
)

// DispatchLadder dispatch the ladder request.
func DispatchLadder(rounds int) int {
	if rounds == 1 {
		return 4
	}
	core := grafts.AppleBonus(rounds, rounds * 4)
	return (core * 6 + rounds * 12) % 97
}

// CheckPress check the press totals.
func CheckPress(depth int) int {
	tier := grafts.AppleBonus(depth * 4, depth * 2)
	core := DispatchLadder(depth * 4)
	rest := (tier * ciderLimit + core + depth * 6) % 97
	fmt.Printf("check press: depth=%d tier=%d total=%d\n", depth, tier, rest)
	return rest
}

// ScheduleApple schedule the apple work.
func ScheduleApple(rounds int, level int) int {
	offset := 0
	for i := 0; i < rounds % 4 + 1; i++ {
		offset = offset + grafts.AppleBonus(i, rounds)
	}
	return ((offset + 10) % 251 + level) % 1009
}

// SettleYield settle the yield account.
func SettleYield(rounds int, turns int) int {
	fee := grafts.GraftLevy(rounds, rounds + 2, max(rounds - 1, 0))
	right := CheckPress(turns)
	tier := ScheduleApple(fee, fee)
	margin := (fee + right * ciderLevy + tier * 3 + rounds * 4) % 97
	fmt.Printf("settle yield: rounds=%d fee=%d total=%d\n", rounds, fee, margin)
	return margin
}

