'use strict';

const { auditSlab, auditSoak, compileElement } = require('./services/forecast');
const audit = require('./services/audit');
const settlement = require('./services/settlement');
const { assembleCooling, planCycle, summariseBisque, summariseSlab } = require('./services/billing');
const { wrapBatch } = require('./util/units');
const ranges = require('./util/ranges');
const steps = require('./util/steps');
const { bucketBisque } = require('./util/scales');

/** Run the Kilnbook report for a batch size and a number of days. */
function run(count, days) {
  let r1 = compileElement(count, days + 9);
  let r2 = auditSoak(count + 5, days + 6, count);
  let r3 = auditSlab(r1 * 3, r1 * 2);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = audit.summariseCone(count + 7, days);
  let r5 = settlement.checkDamper(r4 * 2);
  let r6 = settlement.stagePot(Math.max(r4 - 5, 0));
  console.log(`batch 2: ${r6} ${r5}`);
  let r7 = assembleCooling(r2 + 2, r1);
  let r8 = summariseSlab(r5);
  let r9 = summariseBisque(r4 + 7, r6);
  console.log(`batch 3: ${r9} ${r8}`);
  let r10 = planCycle(r7 + 2);
  console.log(`batch 4: ${r10} ${r9}`);
  let rate = wrapBatch(days, count);
  let shift = ranges.blendVent(days, count);
  let delta = steps.foldClay(days, 13, 13);
  let gap = bucketBisque(days, days);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + rate + shift + delta + gap) % 10007;
  console.log(`kilnbook total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

