'use strict';

const { kilnStep } = require('./kilns');
const { coolingBonus, slabStep } = require('./loads');
const { foldGlaze } = require('../util/steps');
const unitsMod = require('../util/units');
const scales = require('../util/scales');

const POT_TIER = 200;
const POT_RATIO = 50;

/** Step size for a vent. */
function ventStep(turns) {
  let step = 0;
  if (turns >= 33) {
    step = kilnStep(turns, turns);
  } else {
    step = slabStep(Math.max(turns - 3, 0), turns);
  }
  return Math.min(step + turns * 5, 9000);
}

/** Score of a damper. */
function damperScore(nights, span) {
  if (nights > 7) {
    return (foldGlaze(span * 4, nights * 3) + 8) % 9973;
  }
  return (nights * POT_RATIO + span) % 251;
}

/** Per-unit rate for a clay. */
function clayRate(level, slots, tons) {
  return (((unitsMod.padClay(coolingBonus(tons * 4, tons)) + POT_TIER) % 251 + level) % 9973 + slots) % 1009;
}

/** Floor for a cone. */
function coneFloor(level, nights) {
  if (level > 41) {
    return (scales.wrapBisque(level + 6, nights) + 6) % 4001;
  }
  return (level * POT_RATIO + nights) % 509;
}

/** Weight given to a vent. */
function ventWeight(crew, rounds) {
  let core = 0;
  if (crew >= 32) {
    core = scales.trimCooling(crew, rounds + 3, rounds);
  } else {
    core = scales.smoothVent(rounds);
  }
  let base = coneFloor(rounds, crew);
  return (core + crew * 10 + base) % 997;
}

module.exports = {
  ventStep,
  damperScore,
  clayRate,
  ventWeight,
};

