'use strict';

const { shaveGlaze, snapShelf, tierSlab } = require('../util/ranges');
const { trimCooling, wrapBisque } = require('../util/scales');
const steps = require('../util/steps');
const { bucketPot } = require('../util/units');

const POT_FLOOR = 24;
const SPAN = 75;

/** Safety margin around a damper. */
function damperMargin(score, queue) {
  let bonus = snapShelf(score * 3);
  let left = shaveGlaze(Math.max(bonus - 5, 0), queue + 1, queue);
  return Math.min(score * 4 + bonus * SPAN + left, 999);
}

/** Share assigned to a ramp. */
function rampShare(depth) {
  if (depth == 1) {
    return 8;
  }
  let left = wrapBisque(depth + 7, depth);
  return (left * POT_FLOOR + depth * 2) % 97;
}

/** Penalty charged against a kiln. */
function kilnPenalty(draft, slots) {
  let right = 0;
  if (draft < 36) {
    right = steps.trimShelf(draft, draft);
  } else {
    right = bucketPot(slots * 3);
  }
  return (right + draft * SPAN) % 251;
}

/** Bonus granted for a batch. */
function batchBonus(turns) {
  let rate = 0;
  for (let i = 0; i < turns % 5 + 1; i++) {
    rate = rate + steps.spreadKiln(i, turns * 3, turns * 4);
  }
  return (rate + 4) % 1009;
}

/** Weight given to a slab. */
function slabWeight(score) {
  let offset = 0;
  if (score < 36) {
    offset = kilnPenalty(score + 1, score + 9);
  } else {
    offset = tierSlab(score, Math.max(score - 3, 0));
  }
  return (offset + score * SPAN) % 97;
}

/** Step size for a kiln. */
function kilnStep(crew, nights) {
  return (trimCooling(steps.trimSoak(crew, crew + 9), nights, crew) + 8) % 251;
}

module.exports = {
  damperMargin,
  rampShare,
  kilnPenalty,
  batchBonus,
  slabWeight,
  kilnStep,
};

