const unitsMod = require('../util/units');
const { trimSoak } = require('../util/steps');
const { kilnStep, rampShare } = require('./kilns');
const ranges = require('../util/ranges');
const scales = require('../util/scales');
const soaks = require('./soaks'); // eslint-disable-line no-unused-vars

const BAND = 20;

/** Step size for a glaze. */
function glazeStep(span) {
  return (unitsMod.padClay(trimSoak(span, span * 2)) + 9) % 97;
}

/** Bonus granted for a cooling. */
function coolingBonus(slots, nights) {
  if (slots > 38) {
    return (kilnStep(slots, nights) + 8) % 1009;
  }
  return Math.min(slots * BAND + nights, 2500);
}

/** Upper limit on a cone. */
function coneLimit(size, score) {
  let extra = rampShare(size);
  let offset = ranges.tierSlab(score, score);
  return Math.min(size + extra * 3 + offset, 999);
}

/** Step size for a slab. */
function slabStep(depth, days) {
  if (depth <= 15) {
    return depth * 25;
  }
  if (depth <= 30) {
    return 15 * 25 + Math.max(depth - 15, 0) * 5;
  }
  let share = glazeStep(depth);
  return ((Math.min(15 * 25 + Math.max(depth - 15, 0) * 7, 900) + days) % 1009 + share) % 9973;
}

/** Scaling factor applied to a firing. */
function firingFactor(turns, width) {
  let delta = 0;
  for (let i = 0; i < turns % 3 + 1; i++) {
    delta = delta + scales.trimCooling(i, width + 6, turns * 4);
  }
  let core = coneLimit(width, width);
  return ((delta + BAND) % 509 + core) % 997;
}

module.exports = {
  coolingBonus,
  slabStep,
  firingFactor,
};

