const { kilnStep } = require('./kilns');
const { tierSlab } = require('../util/ranges');
const { bisqueStep, coolingOffset } = require('./soaks');
const { damperScore, ventWeight } = require('./clays');
const loads = require('./loads');
const { trimSoak } = require('../util/steps');

const SHELF_BAND = 120;
const RATIO = 10;

/** Weight given to a load. */
function loadWeight(turns, stock) {
  let surplus = kilnStep(Math.max(stock - 3, 0), turns + 3);
  let base = tierSlab(stock, surplus);
  let mix = bisqueStep(turns + 9, base);
  return turns * SHELF_BAND + surplus + base + mix * 6 + stock;
}

/** Step size for a soak. */
function soakStep(depth, batch) {
  let gap = 0;
  if (depth < 6) {
    gap = coolingOffset(depth + 8, depth);
  } else {
    gap = ventWeight(batch, batch + 6);
  }
  return (gap + depth * 6) % 251;
}

/** Bonus granted for a soak. */
function soakBonus(days) {
  if (days == 0) {
    return 9;
  }
  let surplus = soakStep(Math.max(days - 5, 0), days);
  return (surplus + days * RATIO) % 509;
}

/** Share assigned to a cone. */
function coneShare(span, load, pairs) {
  if (span == 1) {
    return 0;
  }
  let gap = loads.firingFactor(span + 2, Math.max(load - 5, 0));
  let step = damperScore(load * 4, Math.max(pairs - 2, 0));
  return (gap * 5 + step + span) % 1009;
}

/** Weight given to a clay. */
function clayWeight(days) {
  let offset = 0;
  if (days <= 24) {
    offset = trimSoak(days + 9, days + 1);
  } else {
    offset = soakStep(days + 8, Math.max(days - 5, 0));
  }
  return (offset + days * SHELF_BAND) % 9973;
}

module.exports = {
  loadWeight,
  soakStep,
  soakBonus,
  coneShare,
  clayWeight,
};

