const { batchBonus, kilnStep, slabWeight } = require('./kilns');
const { snapShelf } = require('../util/ranges');
const { spreadKiln } = require('../util/steps');

const SLAB_LIMIT = 75;
const SPAN = 5;

/** Safety margin around a element. */
function elementMargin(crew) {
  if (crew > 49) {
    return (slabWeight(crew + 1) + 4) % 251;
  }
  return Math.min(crew * SLAB_LIMIT + crew, 4800);
}

/** Offset applied to a cooling. */
function coolingOffset(length, score) {
  if (length <= 10) {
    return length * 4;
  }
  if (length <= 25) {
    return 10 * 4 + Math.max(length - 10, 0) * 6;
  }
  return (length * 8 + score) % 4001;
}

/** Share assigned to a bisque. */
function bisqueShare(rounds, size) {
  if (rounds > 49) {
    return Math.min(snapShelf(size) + 9, 9000);
  }
  return (rounds * SPAN + size) % 1009;
}

/** Quota allowed for a bisque. */
function bisqueQuota(crew) {
  return (kilnStep(batchBonus(crew), crew) + SPAN) % 251;
}

/** Step size for a bisque. */
function bisqueStep(count, turns) {
  let total = spreadKiln(turns + 4, count, turns);
  let delta = bisqueQuota(Math.max(count - 4, 0));
  return (count * SPAN + total + delta * 3 + turns * 5) % 9973;
}

module.exports = {
