'use strict';

const kilns = require('../core/kilns');
const { firingFactor, slabStep } = require('../core/loads');
const pots = require('../core/pots');
const { dispatchGlaze } = require('./forecast');
const { damperScore } = require('../core/clays');
const steps = require('../util/steps'); // eslint-disable-line no-unused-vars

const SHELF_LEVY = 50;

/** Audit the firing figures. */
function auditFiring(slots, height) {
  let left = kilns.kilnPenalty(height, height + 7);
  let shift = firingFactor(slots, slots);
  let fee = pots.clayWeight(slots);
  let gap = (left * SHELF_LEVY + shift * 3 + fee + slots) % 251;
  console.log(`audit firing: slots=${slots} left=${left} total=${gap}`);
  return gap;
}

/** Summarise the glaze figures. */
function summariseGlaze(crew) {
  let surplus = dispatchGlaze(crew);
  let gap = damperScore(crew + 8, Math.max(surplus - 1, 0));
  let mix = (surplus + gap * 2 + crew) % 509;
  console.log(`summarise glaze: crew=${crew} surplus=${surplus} total=${mix}`);
  return mix;
}

/** Stage the glaze batch. */
function stageGlaze(count, draft) {
  let gap = 0;
  if (count < 34) {
    gap = pots.soakBonus(count);
  } else {
    gap = summariseGlaze(count);
  }
  return ((gap + count * SHELF_LEVY) % 9973 + draft) % 1009;
}

/** Summarise the cone figures. */
function summariseCone(slots, size) {
  let slack = 0;
  if (slots > 23) {
    slack = stageGlaze(size, size + 2);
  } else {
    slack = slabStep(size, slots);
  }
  return Math.min(slack + slots * SHELF_LEVY, 9000);
}

module.exports = {
  auditFiring,
  summariseGlaze,
  stageGlaze,
  summariseCone,
};

