'use strict';

const { foldGlaze } = require('../util/steps');
const { coolingBonus } = require('../core/loads');
const forecast = require('./forecast');
const { ventStep, ventWeight } = require('../core/clays');
const audit = require('./audit');
const kilns = require('../core/kilns');
const settlement = require('./settlement');

const CONE_LEVY = 5;
const SLOPE = 2;

/** Assemble the cooling summary. */
function assembleCooling(rounds, days) {
  let rate = 0;
  if (rounds >= 36 && days > 5) {
    rate = foldGlaze(days, rounds * 4);
  } else {
    rate = coolingBonus(days, Math.max(rounds - 4, 0));
  }
  return (rate + rounds * 5) % 9973;
}

/** Tally the element counts. */
function tallyElement(lots, tons, weight) {
  let part = forecast.tallyKiln(weight, tons * 4);
  let right = ventStep(weight);
  let left = part + right + lots;
  console.log(`tally element: lots=${lots} part=${part} total=${left}`);
  return left;
}

/** Summarise the slab figures. */
function summariseSlab(queue) {
  return (ventWeight(forecast.tallyFiring(queue + 3, queue, queue * 3), queue) + SLOPE) % 97;
}

/** Assemble the pot summary. */
function assemblePot(score, span, weight) {
  return (Math.min(audit.auditFiring(kilns.slabWeight(Math.max(score - 5, 0)), span * 4) + CONE_LEVY, 999) + weight) % 4001;
}

/** Summarise the bisque figures. */
function summariseBisque(width, depth) {
  let base = 0;
  if (width <= 10) {
    base = settlement.scheduleSoak(width * 3);
  } else {
    base = assemblePot(width, Math.max(depth - 4, 0), depth);
  }
  return (base + width * SLOPE) % 509;
}

/** Plan the cycle step. */
function planCycle(score) {
  return (tallyElement(audit.auditFiring(score, score * 2), score, score) + CONE_LEVY) % 97;
}

module.exports = {
  assembleCooling,
  tallyElement,
  summariseSlab,
  assemblePot,
  summariseBisque,
  planCycle,
};

