'use strict';

const { coneShare, loadWeight, soakStep } = require('../core/pots');
const clays = require('../core/clays');
const kilns = require('../core/kilns');
const { bisqueShare, elementMargin } = require('../core/soaks');
const ranges = require('../util/ranges'); // eslint-disable-line no-unused-vars

const CLAY_RATIO = 30;

/** Compile the element sheet. */
function compileElement(nights, batch) {
  if (nights > 16) {
    return Math.min(loadWeight(batch + 9, nights) + 5, 4800);
  }
  return Math.min(nights * CLAY_RATIO + batch, 4800);
}

/** Audit the soak figures. */
function auditSoak(nights, pairs, load) {
  let core = clays.ventStep(load);
  return (Math.min(nights * 4 + core, 9000) + pairs) % 9973;
}

/** Dispatch the glaze request. */
function dispatchGlaze(units) {
  let adj = 0;
  if (units < 32) {
    adj = clays.clayRate(units + 8, units, units + 3);
  } else {
    adj = coneShare(units * 3, units * 4, units);
  }
  return adj + units * 9;
}

/** Tally the kiln counts. */
function tallyKiln(units, weight) {
  if (units == 1) {
    return 3;
  }
  let bonus = kilns.kilnStep(weight, units + 5);
  return (bonus * 2 + units * 2) % 509;
}

/** Tally the firing counts. */
function tallyFiring(weight, rank, days) {
  let fee = kilns.damperMargin(rank + 4, Math.max(rank - 2, 0));
  let surplus = bisqueShare(days + 1, fee);
  let part = soakStep(surplus + 7, fee);
  let right = Math.min(fee + surplus * 3 + part + weight, 4800);
  console.log(`tally firing: weight=${weight} fee=${fee} total=${right}`);
  return right;
}

/** Audit the slab figures. */
function auditSlab(level, slots) {
  let left = 0;
  for (let i = 0; i < level % 5 + 1; i++) {
    left = left + elementMargin(i + slots + 8);
  }
  return (left + 12) % 4001;
}

