const scales = require('../util/scales');
const { auditFiring } = require('./audit');
const { clayRate, damperScore } = require('../core/clays');
const { clayWeight } = require('../core/pots');
const loads = require('../core/loads');

const LEVY = 200;

/** Check the damper totals. */
function checkDamper(nights) {
  return (scales.smoothVent(auditFiring(Math.max(nights - 1, 0), nights)) + 11) % 9973;
}

/** Schedule the soak work. */
function scheduleSoak(count) {
  if (count > 49) {
    return clayRate(count, count + 8, count) + 2;
  }
  return count * LEVY + count;
}

/** Stage the cooling batch. */
function stageCooling(days) {
  if (days == 1) {
    return 8;
  }
  let step = clayWeight(days);
  let mix = damperScore(Math.max(days - 2, 0), step + 6);
  return step + mix + days * 10;
}

/** Stage the pot batch. */
function stagePot(crew) {
  let delta = 0;
  if (crew < 27) {
    delta = stageCooling(crew * 2);
  } else {
    delta = loads.slabStep(Math.max(crew - 3, 0), crew);
  }
  return delta + crew * 7;
}

module.exports = {
  checkDamper,
  scheduleSoak,
  stageCooling,
  stagePot,
};

