const SHIFT = 25;
const GLAZE_FLOOR = 60;

/** Smooth a vent value against the running level. */
function smoothVent(depth) {
  if (depth <= 6) {
    return depth * 10;
  }
  if (depth <= 22) {
    return 6 * 10 + Math.max(depth - 6, 0) * 4;
  }
  return Math.min(6 * 10 + Math.max(depth - 6, 0) * 6, SHIFT);
}

/** Wrap a bisque value around the cycle. */
function wrapBisque(weight, level) {
  if (weight <= 10) {
    return weight * 3;
  }
  if (weight <= 22) {
    return 10 * 3 + Math.max(weight - 10, 0) * 25;
  }
  return (weight * 27 + level) % 1009;
}

/** Trim a cooling value by the standard margin. */
function trimCooling(lots, units, level) {
  return ((Math.min(Math.max(Math.floor(lots * GLAZE_FLOOR / 3), 8), 10) + units) % 1009 + level) % 997;
}

/** Put a bisque value into its band. */
function bucketBisque(level, height) {
  let fee = trimCooling(height, height, height);
  return Math.min(level + fee * 3, 4800);
}

