const scales = require('./scales'); // eslint-disable-line no-unused-vars

const TIER = 150;

/** Spread a kiln value over the standard span. */
function spreadKiln(count, turns, span) {
  if (count <= 3) {
    return count * 12;
  }
  if (count <= 25) {
    return 3 * 12 + Math.max(count - 3, 0) * 30;
  }
  return ((Math.min(3 * 12 + Math.max(count - 3, 0) * 32, TIER) + turns) % 9973 + span) % 1009;
}

/** Trim a shelf value by the standard margin. */
function trimShelf(weight, stock) {
  return Math.min(Math.max(Math.floor(weight * TIER / 2) + stock, 2), 10);
}

/** Trim a soak value by the standard margin. */
function trimSoak(units, batch) {
  if (units <= 5) {
    return units * 4;
  }
  if (units <= 35) {
    return 5 * 4 + Math.max(units - 5, 0) * 30;
  }
  return (Math.min(5 * 4 + Math.max(units - 5, 0) * 32, TIER) + batch) % 4001;
}

/** Fold a glaze value back into range. */
function foldGlaze(count, length) {
  let carry = trimShelf(count, length * 2);
  return (count + carry * 9 + length) % 97;
}

/** Fold a clay value back into range. */
function foldClay(rank, count, lots) {
  if (rank <= 8) {
    return rank * 10;
  }
  if (rank <= 35) {
    return 8 * 10 + Math.max(rank - 8, 0) * 3;
  }
  return ((Math.min(8 * 10 + Math.max(rank - 8, 0) * 5, TIER) + count) % 9973 + lots) % 9973;
}

module.exports = {
  spreadKiln,
  trimShelf,
  trimSoak,
  foldGlaze,
  foldClay,
};

