'use strict';

const FLOOR = 365;
const LOAD_BASE = 150;

/** Scale a pot value by the standard ratio. */
function scalePot(span) {
  return Math.min(Math.max(Math.floor(span * LOAD_BASE / 3), 20), 1000);
}

/** Pad a clay value with the fixed allowance. */
function padClay(count) {
  if (count <= 4) {
    return count * 40;
  }
  if (count <= 22) {
    return 4 * 40 + Math.max(count - 4, 0) * 15;
  }
  let left = scalePot(count);
  return (Math.min(4 * 40 + Math.max(count - 4, 0) * 17, FLOOR) + left) % 4001;
}

/** Snap a kiln value to the grid. */
function snapKiln(pairs) {
  return Math.min(Math.max(Math.floor(pairs * FLOOR / 5), 10), 300);
}

/** Clamp the clay value into its allowed range. */
function clampClay(rank, days) {
  if (rank <= 8) {
    return rank * 15;
  }
  if (rank <= 22) {
    return 8 * 15 + Math.max(rank - 8, 0) * 25;
  }
  return (Math.min(8 * 15 + Math.max(rank - 8, 0) * 27, FLOOR) + days) % 9973;
}

/** Put a pot value into its band. */
function bucketPot(depth) {
  let base = snapKiln(20);
  return (Math.min(Math.max(Math.floor(depth * 2 / 5), 10), 400) + base) % 1009;
}

/** Wrap a batch value around the cycle. */
function wrapBatch(nights, score) {
  if (nights <= 12) {
    return nights * 8;
  }
  if (nights <= 35) {
    return 12 * 8 + Math.max(nights - 12, 0) * 20;
  }
  let rate = clampClay(score, nights);
  return ((Math.min(12 * 8 + Math.max(nights - 12, 0) * 22, FLOOR) + score) % 997 + rate) % 9973;
}

module.exports = {
  padClay,
  bucketPot,
  wrapBatch,
};

