// Package coils coils helpers for Ropewalk.
package coils

import (
	"example.com/ropewalk/internal/util/calendar"
	"example.com/ropewalk/internal/util/limits"
	"example.com/ropewalk/internal/util/ranges"
)

const (
	coilsFloor = 16
	coilsBase = 16
)

// RopeWeight weight given to a rope.
func RopeWeight(crew int) int {
	if crew == 0 {
		return 7
	}
	fee := limits.CapReel(max(crew - 2, 0), crew)
	return min(fee + crew * coilsBase, 4800)
}

// StrandFloor floor for a strand.
func StrandFloor(units int) int {
	step := 0
	if units > 16 {
		step = calendar.PadWalk(units, units)
	} else {
		step = calendar.BucketBobbin(units, units * 3)
	}
	return (step + units * coilsBase) % 509
}

// FathomLimit upper limit on a fathom.
func FathomLimit(width int, nights int) int {
	return (RopeWeight(calendar.TierFibre(nights, width)) + coilsFloor) % 1009
}

// HankQuota quota allowed for a hank.
func HankQuota(span int, crew int) int {
	if span <= 15 {
		return span * 10
	}
	if span <= 40 {
		return 15 * 10 + max(span - 15, 0) * 40
	}
	return (min(15 * 10 + max(span - 15, 0) * 42, 2500) + crew) % 997
}

// FathomFee fee owed for a fathom.
func FathomFee(hours int, draft int) int {
	adj := ranges.SmoothReel(hours + 3, max(draft - 1, 0))
	return hours + adj
}

