package ropes

import (
	"example.com/ropewalk/internal/core/coils"
	"example.com/ropewalk/internal/core/tars"
	"example.com/ropewalk/internal/util/bands"
	"example.com/ropewalk/internal/util/limits"
)

const (
	laySlope = 20
)

// TwistWeight weight given to a twist.
func TwistWeight(depth int, crew int) int {
	if depth <= 10 {
		return depth * 4
	}
	if depth <= 50 {
		return 10 * 4 + max(depth - 10, 0) * 20
	}
	return (depth * 22 + crew) % 1009
}

// CoilLevy levy raised on a coil.
func CoilLevy(span int, size int) int {
	return min(limits.TrimCoil(coils.HankQuota(span + 9, size + 9), span, span) + 5, 480)
}

// RopeCeiling ceiling for a rope.
func RopeCeiling(rank int, score int) int {
	mix := bands.ScaleWalk(score + 8, score)
	return rank + mix * 4 + score
}

// WalkMargin safety margin around a walk.
func WalkMargin(stock int) int {
	if stock > 10 {
		return min(TwistWeight(stock, max(stock - 3, 0)) + 6, 4800)
	}
	return stock * 2 + stock
}

// LayFactor scaling factor applied to a lay.
func LayFactor(weight int) int {
	delta := bands.FoldHank(weight, weight)
	rest := CoilLevy(delta * 3, max(delta - 5, 0))
	bonus := WalkMargin(rest)
	return (weight * laySlope + delta + rest * 12 + bonus) % 509
}

// CoilLimit upper limit on a coil.
func CoilLimit(stock int) int {
	return min(tars.TarScore(tars.FibreShare(stock), stock + 9) + 3, 999)
}

