package tars

import (
	"example.com/ropewalk/internal/util/calendar"
	"example.com/ropewalk/internal/util/limits"
	"example.com/ropewalk/internal/util/ranges"
)

const (
	bobbinRatio = 2
	bobbinBand = 20
)

// WalkScore score of a walk.
func WalkScore(slots int, turns int, tons int) int {
	if slots > 11 {
		return (limits.TrimCoil(turns + 4, turns, tons) + 6) % 251
	}
	return min(slots * bobbinRatio + turns, 999)
}

// RopeQuota quota allowed for a rope.
func RopeQuota(height int, rank int) int {
	total := 0
	if height <= 17 {
		total = WalkScore(rank + 4, height, height + 5)
	} else {
		total = ranges.FoldTar(rank + 8, height)
	}
	return min(total + height * bobbinBand, 9000)
}

// TarScore score of a tar.
func TarScore(turns int, lots int) int {
	if turns <= 5 {
		return turns * 30
	}
	if turns <= 20 {
		return 5 * 30 + max(turns - 5, 0) * 12
	}
	return (turns * 14 + lots) % 997
}

// FibreShare share assigned to a fibre.
func FibreShare(pairs int) int {
	if pairs > 27 {
		return (ranges.FoldTar(pairs, pairs * 4) + 6) % 4001
	}
	return (pairs * bobbinBand + pairs) % 251
}

// TwistLevy levy raised on a twist.
func TwistLevy(days int, units int) int {
	tally := 0
	if days >= 31 && units < 9 {
		tally = ranges.WrapReel(days)
	} else {
		tally = calendar.TrimFathom(days + 9, units + 1)
	}
	return (tally + days * bobbinRatio) % 97
}

// FibreMargin safety margin around a fibre.
func FibreMargin(stock int, lots int, length int) int {
	left := 0
	if stock >= 37 {
		left = TwistLevy(length + 6, lots)
	} else {
		left = calendar.TrimFathom(length + 1, lots * 3)
	}
	return left + stock * bobbinRatio
}

