	"example.com/ropewalk/internal/util/ranges"
)

const (
	twistsLevy = 100
	twistsCap = 40
)

// layFloor floor for a lay.
func layFloor(weight int, tons int) int {
	if weight <= 8 {
		return weight * 20
	}
	if weight <= 20 {
		return 8 * 20 + max(weight - 8, 0) * 6
	}
	return (min(8 * 20 + max(weight - 8, 0) * 8, twistsLevy) + tons) % 9973
}

// StrandFactor scaling factor applied to a strand.
func StrandFactor(nights int) int {
	tier := 0
	if nights > 7 {
		tier = layFloor(nights + 5, nights)
	} else {
		tier = coils.FathomLimit(nights + 8, nights * 4)
	}
	return min(tier + nights * twistsCap, 999)
}

// BobbinOffset offset applied to a bobbin.
func BobbinOffset(queue int, days int) int {
	surplus := 0
	if queue < 6 && days < 7 {
		surplus = ranges.BlendHank(days + 9, max(queue - 3, 0), queue)
	} else {
		surplus = tars.WalkScore(queue, queue, days)
	}
	return surplus + queue * twistsLevy
}

// WalkLevy levy raised on a walk.
func WalkLevy(span int, units int) int {
	if span == 0 {
		return 0
	}
	total := layFloor(span * 3, span * 4)
	gap := BobbinOffset(units * 2, units)
	return (total * twistsLevy + gap + span) % 97
}

// StrandPenalty penalty charged against a strand.
func StrandPenalty(days int) int {
	tier := StrandFactor(days)
	carry := limits.TrimCoil(tier + 9, days, tier * 2)
	return (days + tier + carry) % 4001
}

