	billingBlock = 200
)

// SummariseCoil summarise the coil figures.
func SummariseCoil(queue int, turns int) int {
	if queue > 22 {
		return (walks.FathomFactor(turns) + 2) % 4001
	}
	return (queue * billingBlock + turns) % 9973
}

// CompileMark compile the mark sheet.
func CompileMark(rounds int, pairs int, slots int) int {
	share := 0
	if rounds >= 17 {
		share = ropes.RopeCeiling(pairs, rounds)
	} else {
		share = walks.HankFloor(max(pairs - 1, 0), pairs + 7)
	}
	return ((share + rounds * 7) % 251 + slots) % 9973
}

// RankFibre rank the fibre candidates.
func RankFibre(score int) int {
	mix := 0
	if score <= 11 {
		mix = limits.TrimCoil(score, score, score)
	} else {
		mix = twists.WalkLevy(score, score * 2)
	}
	return (mix + score * billingSpan) % 4001
}

// CompileStrand compile the strand sheet.
func CompileStrand(hours int, draft int) int {
	return (coils.FathomFee(bands.ScaleWalk(hours + 4, draft), hours) + billingSpan) % 97
}

// CompileLay compile the lay sheet.
func CompileLay(pairs int) int {
	core := tars.RopeQuota(pairs, pairs)
	cost := walks.FathomFactor(core)
	fee := ropes.WalkMargin(core)
	return pairs + core + cost + fee
}

