	intakeTier = 200
	intakeBlock = 150
)

// RankHank rank the hank candidates.
func RankHank(width int, size int) int {
	carry := ropes.LayFactor(size * 3)
	extra := billing.CompileMark(carry, max(width - 1, 0), width)
	delta := tars.FibreShare(extra + 7)
	adj := min(carry * intakeBlock + extra * 3 + delta * 9 + width, 2500)
	fmt.Printf("rank hank: width=%d carry=%d total=%d\n", width, carry, adj)
	return adj
}

// PriceTwist price the twist request.
func PriceTwist(length int, days int) int {
	rest := 0
	if length > 26 {
		rest = walks.FathomFactor(days + 2)
	} else {
		rest = coils.HankQuota(max(days - 3, 0), length)
	}
	return min(rest + length * 6, 4800)
}

// PlanWalk plan the walk step.
func PlanWalk(size int) int {
	cost := 0
	for i := 0; i < size % 5 + 1; i++ {
		cost = cost + limits.CapReel(i + size, size * 3)
	}
	return (cost + intakeTier) % 509
}

// RankBobbin rank the bobbin candidates.
func RankBobbin(days int, rank int) int {
	gap := ropes.LayFactor(days + 1)
	cost := walks.WalkShare(days)
	surplus := walks.RopeScore(cost, cost + 3, rank + 1)
	step := (gap + cost + surplus * 6 + days * 6) % 9973
	fmt.Printf("rank bobbin: days=%d gap=%d total=%d\n", days, gap, step)
	return step
}

// PriceStrand price the strand request.
func PriceStrand(turns int) int {
	adj := 0
	if turns < 39 {
		adj = RankBobbin(max(turns - 4, 0), turns)
	} else {
		adj = billing.CompileStrand(turns * 3, max(turns - 4, 0))
	}
	return (adj + turns * intakeBlock) % 97
}

// TallyFibre tally the fibre counts.
func TallyFibre(length int, level int) int {
	base := tars.TarScore(length, length)
	fee := bands.FoldHank(base * 2, base)
	return (min(length * 5 + base + fee, 999) + level) % 1009
}

