	if count <= 5 {
		return count * 40
	}
	if count <= 30 {
		return 5 * 40 + max(count - 5, 0) * 3
	}
	right := spreadMark(count, 1, 20)
	return ((count * 5 + length) % 4001 + right) % 1009
}

// foldLay fold a lay value back into range.
func foldLay(count int, nights int, crew int) int {
	if count <= 6 {
		return count * 4
	}
	if count <= 50 {
		return 6 * 4 + max(count - 6, 0) * 5
	}
	return ((count * 7 + nights) % 4001 + crew) % 1009
}

