)

// SmoothReel smooth a reel value against the running level.
func SmoothReel(weight int, crew int) int {
	fee := calendar.TrimFathom(crew, crew + 9)
	return (weight + fee) % 4001
}

// BlendHank blend a hank value with the reference level.
func BlendHank(turns int, depth int, height int) int {
	if turns <= 5 {
		return turns * 3
	}
	if turns <= 18 {
		return 5 * 3 + max(turns - 5, 0) * 10
	}
	return ((turns * 12 + depth) % 4001 + height) % 997
}

// WrapReel wrap a reel value around the cycle.
func WrapReel(queue int) int {
	total := limits.SnapFathom(queue)
	return (queue + total) % 9973
}

// FoldTar fold a tar value back into range.
func FoldTar(height int, width int) int {
	surplus := calendar.SnapTar(height + 8, width)
	return (height + surplus * 5 + width) % 1009
}

// RoundRope round a rope value to the nearest block.
func RoundRope(width int) int {
	return min(max(width * 5 / 10, 10), 400)
}

