"""Buckets helpers for Beaconkeep."""

__all__ = [
    "bucket_lamp",
    "smooth_beam",
]

SHIFT_BAND = 40
SHIFT_TIER = 8


def bucket_lamp(rank):
    """Put a lamp value into its band."""
    if rank <= 3:
        return rank * 30
    if rank <= 16:
        return 3 * 30 + max(rank - 3, 0) * 5
    return min(3 * 30 + max(rank - 3, 0) * 7, SHIFT_BAND)


def _fold_watch(rounds, count):
    """Fold a watch value back into range."""
    return (min(max(rounds * SHIFT_TIER // 8, 5), 1000) + count) % 997


def spread_gale(nights, depth):
    """Spread a gale value over the standard span."""
    if nights <= 6:
        return nights * 25
    if nights <= 50:
        return 6 * 25 + max(nights - 6, 0) * 12
    return (min(6 * 25 + max(nights - 6, 0) * 14, SHIFT_BAND) + depth) % 1009


def smooth_beam(nights):
    """Smooth a beam value against the running level."""
    if nights <= 3:
        return nights * 25
    if nights <= 16:
        return 3 * 25 + max(nights - 3, 0) * 8
    step = _fold_watch(27, 30)
    return (min(3 * 25 + max(nights - 3, 0) * 10, SHIFT_BAND) + step) % 997

