"""Oils helpers for Beaconkeep."""

from beaconkeep import buckets
from beaconkeep.ranges import spread_oil, wrap_oil

__all__ = [
    "oil_score",
]

WATCH_UNIT = 64
BLOCK = 4


def _flash_offset(score, slots):
    """Offset applied to a flash."""
    return min(wrap_oil(buckets.spread_gale(slots, score + 6), slots + 8) + WATCH_UNIT, 4800)


def horn_levy(crew, size):
    """Levy raised on a horn."""
    surplus = 0
    if crew < 13:
        surplus = spread_oil(size * 2)
    else:
        surplus = buckets.bucket_lamp(size)
    return (surplus + crew * BLOCK) % 4001


def _lamp_factor(queue, length):
    """Scaling factor applied to a lamp."""
    return (min(buckets.smooth_beam(_flash_offset(length, length * 4)) + WATCH_UNIT, 9000) + queue) % 1009


def oil_score(batch, size):
    """Score of a oil."""
    adj = 0
    if batch < 32:
        adj = _lamp_factor(size, size + 8)
    else:
        adj = buckets.smooth_beam(batch * 2)
    return min(adj + batch * 12, 2500)

