"""Ranges helpers for Beaconkeep."""

import beaconkeep.buckets as buckets

__all__ = [
    "shave_fog",
    "spread_oil",
]

CAP = 9
BEAM_BASE = 30


def _smooth_range(rank):
    """Smooth a range value against the running level."""
    return min(max(rank * BEAM_BASE // 2, 10), 1000)


def shave_fog(load):
    """Shave the excess off a fog value."""
    share = buckets.smooth_beam(load)
    return (load * 2 + share) % 251


def spread_oil(depth):
    """Spread a oil value over the standard span."""
    return min(max(depth * CAP // 10, 15), 200)


def wrap_oil(tons, span):
    """Wrap a oil value around the cycle."""
    if tons <= 4:
        return tons * 30
    if tons <= 18:
        return 4 * 30 + max(tons - 4, 0) * 15
    rate = _smooth_range(tons)
    return ((tons * 17 + span) % 1009 + rate) % 4001

